import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

import { verifyAdminCookieAuth } from '@/lib/admin-auth';
import { CANONICAL_RULES } from '@/lib/calendar/rules';

function adminSupabase() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  );
}

// GET /api/admin/calendar-governance/coverage
// Live version of the Tier-1 backlog report generated by hand earlier this
// session -- computed on request from rules.json + golden_fixtures, so it
// never goes stale the way a one-off markdown snapshot does.
export async function GET(request: NextRequest) {
  const authError = await verifyAdminCookieAuth(request);
  if (authError) return authError;

  const supabase = adminSupabase();
  const { data: fixtures, error } = await supabase
    .from('golden_fixtures')
    .select('festival_id, approved, expected, source');

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });

  const fixturedSlugs = new Set((fixtures ?? []).map(f => f.festival_id));
  const realFixturesBySlug = new Map<string, number>();
  const approvedBySlug = new Map<string, number>();
  for (const f of fixtures ?? []) {
    const isReal = f.expected != null && !String((f.source as { ref?: string })?.ref ?? '').startsWith('TODO');
    if (isReal) realFixturesBySlug.set(f.festival_id, (realFixturesBySlug.get(f.festival_id) ?? 0) + 1);
    if (f.approved) approvedBySlug.set(f.festival_id, (approvedBySlug.get(f.festival_id) ?? 0) + 1);
  }

  const bySlug = new Map<string, { tradition: string; launchStatus: string; hasFixtureFile: boolean; realFixtures: number; approvedFixtures: number }>();
  for (const rule of CANONICAL_RULES) {
    const existing = bySlug.get(rule.slug);
    const launchStatus = rule.launch_status ?? 'included';
    if (!existing) {
      bySlug.set(rule.slug, {
        tradition: rule.tradition,
        launchStatus,
        hasFixtureFile: fixturedSlugs.has(rule.slug),
        realFixtures: realFixturesBySlug.get(rule.slug) ?? 0,
        approvedFixtures: approvedBySlug.get(rule.slug) ?? 0,
      });
    }
  }

  const rows = Array.from(bySlug.entries()).map(([slug, v]) => ({ slug, ...v }));

  const byTradition: Record<string, { total: number; live: number; liveUnfixtured: number; deferred: number }> = {};
  for (const r of rows) {
    const t = byTradition[r.tradition] ?? { total: 0, live: 0, liveUnfixtured: 0, deferred: 0 };
    t.total += 1;
    if (r.launchStatus === 'included') {
      t.live += 1;
      if (r.realFixtures === 0) t.liveUnfixtured += 1;
    } else {
      t.deferred += 1;
    }
    byTradition[r.tradition] = t;
  }

  return NextResponse.json({
    totalSlugs: rows.length,
    totalFixtureRows: fixtures?.length ?? 0,
    realFixtureRows: Array.from(realFixturesBySlug.values()).reduce((a, b) => a + b, 0),
    approvedFixtureRows: Array.from(approvedBySlug.values()).reduce((a, b) => a + b, 0),
    byTradition,
    rows,
  });
}
